using System.IO;
using EcomCraftStudio.Studio.Setup;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using SwarmUI.Accounts;
using SwarmUI.Backends;
using SwarmUI.Core;
using SwarmUI.Utils;
using SwarmUI.WebAPI;

namespace EcomCraftStudio.Studio;

/// <summary>Standard workflows generated by the server (F57): the built-in templates reference "*/ecomcraft/scene" and "*/ecomcraft/detail",
/// which used to need hand-made workflows on every execution server. The generator reads the blueprint the current model recipe declares for the
/// kind (T118), converts and checks it like a discovered workflow, puts in the recipe variant's model file names (or the administrator's legacy
/// override) and a product image input, and publishes it through <see cref="WorkflowReview"/> with the source "系统生成". It is published only when
/// a ready execution server has every node and model. Administrators can take it down in the review like any workflow; the automatic check never
/// republishes what was taken down. Clients still send only workflow IDs: the graph never comes from or goes to a client.</summary>
[API.APIClass("EcomCraft standard workflows: generate and publish the built-in template workflows from the current model recipe's blueprints.")]
public static class StandardWorkflows
{
    /// <summary>Source label of system generated workflows, shown to reviewers in place of a server name.</summary>
    public const string Source = "系统生成";

    /// <summary>The generated workflows: published ID (matching the templates' "*/ecomcraft/…" names), description, which recipe kind's blueprint
    /// they build from (T118), whether the product repainting pass is added (R13) and, above zero, how many product angle photos the reference-edit
    /// trial wires in (F84, T123). Scene and detail share a kind of blueprint; the templates differ by prompt, and "with a model" is a prompt
    /// fragment (F53). The reference-edit kinds share one kind of blueprint: they differ only in how many SwarmLoadImageB64 inputs are wired.</summary>
    private sealed record KindEntry(string Kind, string RecipeKind, string Id, string Description, bool AddProductInpaint, int EditAngles = 0);

    private static readonly KindEntry[] Kinds =
    [
        new("scene", "scene", $"{Source}/ecomcraft/scene", "系统按当前配方生成的场景图工作流（围绕放好的商品重绘场景，出图后贴回原商品）。", true),
        new("detail", "detail", $"{Source}/ecomcraft/detail", "系统按当前配方生成的细节图工作流（围绕放好的商品重绘场景，出图后贴回原商品）。", true),
        new("reference-edit-1", "reference-edit", ReferenceEditId(1), "系统按当前配方生成的直接融合工作流（试用版，1 张商品角度图）。", false, 1),
        new("reference-edit-2", "reference-edit", ReferenceEditId(2), "系统按当前配方生成的直接融合工作流（试用版，2 张商品角度图）。", false, 2),
        new("reference-edit-3", "reference-edit", ReferenceEditId(3), "系统按当前配方生成的直接融合工作流（试用版，3 张商品角度图）。", false, 3)
    ];

    /// <summary>Whether a published ID is one of the generated standard workflows.</summary>
    public static bool IsStandard(string id) => Kinds.Any(item => item.Id == id);

    /// <summary>Whether a standard workflow repaints the scene around a placed product canvas (R13): the transparent-canvas input check applies only to these,
    /// not to the reference-edit trial whose product inputs are white-flattened photos (F84).</summary>
    public static bool NeedsProductCanvas(string id) => Kinds.Any(item => item.Id == id && item.AddProductInpaint);

    /// <summary>The published ID of the reference-edit trial's workflow for a product with this many angle photos (F84): one workflow per angle count, 1–3.</summary>
    public static string ReferenceEditId(int angles) => $"{Source}/ecomcraft/reference-edit-{Math.Clamp(angles, 1, 3)}";

    /// <summary>The kind name of the reference-edit workflow for this many angle photos, as <see cref="Unavailable"/> takes it.</summary>
    public static string ReferenceEditKind(int angles) => $"reference-edit-{Math.Clamp(angles, 1, 3)}";

    /// <summary>ID of the product image input added to every generated workflow, so the templates' "@image" field and product preservation work.
    /// The graph loads it (N10) with a SwarmLoadImageB64 node straight from the request (A34: the canvas is never uploaded to the execution server's
    /// input folder): the product canvas is transparent around the product, its alpha becomes the mask, and only the scene around the product
    /// is generated, so surface, shadows and scale follow the real product. The product is still pasted back after generation.</summary>
    public const string ProductImageParam = ProductInpaintRules.ProductParam;

    /// <summary>Folder of the shipped blueprints, set at startup.</summary>
    private static string BlueprintDir;

    /// <summary>The last result per kind: state ("published", "taken_down", "missing_blueprint", "unsupported", "missing_dependencies", "no_server", "failed") and problems.</summary>
    private static readonly Dictionary<string, (string State, List<string> Problems)> Status = new();

    /// <summary>Protects <see cref="Status"/> and serializes generation runs.</summary>
    private static readonly object Lock = new();

    /// <summary>Stops the startup check when the extension shuts down.</summary>
    private static readonly CancellationTokenSource StopSource = new();

    /// <summary>Remembers the blueprint folder and starts the background check: it retries every minute until every kind is settled, so
    /// it also works when execution servers come online after startup.</summary>
    public static void Init(string extensionFolder)
    {
        BlueprintDir = Path.Combine(extensionFolder, "Templates", "blueprints");
        _ = Task.Run(async () =>
        {
            for (int attempt = 0; attempt < 60 && !StopSource.IsCancellationRequested && !Program.GlobalProgramCancel.IsCancellationRequested; attempt++)
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(attempt == 0 ? 30 : 60), StopSource.Token);
                }
                catch (OperationCanceledException)
                {
                    return;
                }
                try
                {
                    if (Ensure(false).All(item => item.State is "published" or "taken_down" or "missing_blueprint" or "unsupported"))
                    {
                        return;
                    }
                }
                catch (Exception ex)
                {
                    Logs.Error($"EcomCraft standard workflow check failed: {ex.GetType().Name}: {ex.Message}");
                }
            }
        });
    }

    /// <summary>Stops the background check.</summary>
    public static void Shutdown() => StopSource.Cancel();

    /// <summary>Why the standard workflow of a kind ("scene", "detail" or "reference-edit-N") cannot be used now, in plain words for the page;
    /// null once it is published. Names missing nodes or models only, never addresses or graphs.</summary>
    public static string Unavailable(string kind)
    {
        KindEntry entry = Kinds.FirstOrDefault(item => item.Kind == kind);
        if (entry.Id is null || WorkflowReview.IsPublished(entry.Id))
        {
            return null;
        }
        (string State, List<string> Problems) known;
        lock (Lock)
        {
            if (!Status.TryGetValue(kind, out known))
            {
                known = ("not_checked", new List<string>());
            }
        }
        return known.State switch
        {
            "missing_blueprint" => "缺少标准工作流蓝图文件。请管理员更新 EcomCraft 后重启服务。",
            "unsupported" => known.Problems.Count > 0
                ? $"当前模型配方无法生成它：{string.Join("；", known.Problems)}"
                : "标准工作流蓝图无法转换。请管理员查看服务器日志。",
            "missing_dependencies" => $"执行服务器缺少它需要的节点或模型：{string.Join("；", known.Problems)}。请管理员安装后在“管理 → 标准工作流”中点“初始化”。",
            "no_server" => "检查时还没有在线的执行服务器。服务器上线后一分钟内会自动重试，也可以请管理员在“管理 → 标准工作流”中点“初始化”。",
            "taken_down" => "它已被管理员在工作流审核中下架。",
            "failed" => "发布没有成功。请管理员在“管理 → 标准工作流”中点“初始化”重试。",
            _ => "服务刚启动，正在检查执行服务器，请一分钟后再试。"
        };
    }

    /// <summary>Reads the blueprint the current recipe declares for the kind (T118), converts and wires it like <see cref="StandardWorkflowGraph"/>
    /// describes. Returns the built graph with a problem code ("missing_blueprint" or "unsupported") and plain-language notes when it cannot build.</summary>
    private static (JObject Prompt, JObject Metadata, JObject Values, string Canvas, string Problem, List<string> Notes) Blueprint(KindEntry kind)
    {
        ModelRecipeRules.EffectiveModels effective = ModelRecipes.Current();
        if (effective.Recipe is null)
        {
            return (null, null, null, null, "unsupported", [.. effective.Problems, "没有可用的模型配方，无法生成标准工作流。"]);
        }
        if (!effective.Recipe.Blueprints.TryGetValue(kind.RecipeKind, out ModelRecipeRules.BlueprintEntry blueprint))
        {
            return (null, null, null, null, "unsupported", [$"当前配方 {effective.Recipe.Id} 未声明 {kind.RecipeKind} 蓝图。"]);
        }
        string path = Path.Combine(BlueprintDir ?? "", blueprint.File);
        string json;
        try
        {
            if (!File.Exists(path))
            {
                return (null, null, null, null, "missing_blueprint", new List<string>());
            }
            json = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Logs.Error($"EcomCraft could not read the standard workflow blueprint: {ex.Message}");
            return (null, null, null, null, "missing_blueprint", new List<string>());
        }
        (JObject prompt, JObject metadata, JObject values, string problem, List<string> notes) = StandardWorkflowGraph.Build(json, kind.AddProductInpaint,
            kind.EditAngles, effective.Recipe, effective.Files, blueprint, Environment.CurrentDirectory,
            Program.ServerSettings.Paths.ModelRoot.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
        return (prompt, metadata, values, json, problem, notes);
    }

    /// <summary>Generates and publishes the standard workflows that are missing or out of date. <paramref name="force"/> (the administrator's
    /// "initialize" button) also republishes workflows an administrator took down. Returns the state of every kind.</summary>
    public static List<(string Kind, string Id, string State, List<string> Problems)> Ensure(bool force)
    {
        lock (Lock)
        {
            WorkflowReview.Restore();
            List<(string, string, string, List<string>)> result = [];
            List<BackendHandler.T2IBackendData> ready = [.. ExecutionServers.All.Where(ExecutionServers.IsReady)];
            // Kinds may share a blueprint file: convert each file once per run (R13). The edit trial's kinds share the file but wire a different
            // number of product angles into it (F84), so they cache apart by their angle count.
            Dictionary<string, (JObject Prompt, JObject Metadata, JObject Values, string Canvas, string Problem, List<string> Notes)> blueprints = [];
            ModelRecipeRules.EffectiveModels effective = ModelRecipes.Current();
            foreach (KindEntry kind in Kinds)
            {
                ModelRecipeRules.BlueprintEntry entry = effective.Recipe?.Blueprints.GetValueOrDefault(kind.RecipeKind);
                string cacheKey = (entry?.File ?? "") + (kind.EditAngles > 0 ? $":{kind.EditAngles}" : "");
                if (!blueprints.TryGetValue(cacheKey, out (JObject Prompt, JObject Metadata, JObject Values, string Canvas, string Problem, List<string> Notes) built))
                {
                    built = Blueprint(kind);
                    blueprints[cacheKey] = built;
                }
                (string state, List<string> problems) = Publish(kind.Id, kind.Description, built.Prompt, built.Metadata, built.Values, built.Canvas, built.Problem,
                    [.. built.Notes, .. effective.Problems], ready, force);
                Status[kind.Kind] = (state, problems);
                result.Add((kind.Kind, kind.Id, state, problems));
            }
            return result;
        }
    }

    /// <summary>Publishes one kind when the blueprint converts and a ready execution server can run it; otherwise reports why not.</summary>
    private static (string State, List<string> Problems) Publish(string id, string description, JObject prompt, JObject metadata, JObject values, string canvas,
        string problem, List<string> notes, List<BackendHandler.T2IBackendData> ready, bool force)
    {
        WorkflowReview.Record record = WorkflowReview.Get(id);
        if (!force && record?.Status == WorkflowReview.Unpublished)
        {
            return ("taken_down", new List<string>());
        }
        if (problem is not null)
        {
            return (problem, notes.Take(5).ToList());
        }
        if (ready.Count == 0)
        {
            return ("no_server", new List<string>());
        }
        List<string> problems = [];
        bool runnable = false;
        foreach (BackendHandler.T2IBackendData data in ready)
        {
            if (NativeWorkflowParameters.Supports(prompt, metadata, values, ExecutionServers.Schema(data), out List<string> missing))
            {
                runnable = true;
                break;
            }
            problems.AddRange(missing.Where(item => !problems.Contains(item)).Take(3));
        }
        if (!runnable)
        {
            return ("missing_dependencies", problems.Take(5).ToList());
        }
        string fingerprint = WorkflowCatalogFilter.Fingerprint(new JObject { ["prompt"] = prompt, ["parameters"] = metadata, ["values"] = values });
        if (WorkflowReview.IsPublished(id) && record?.Snapshot?.Fingerprint == fingerprint)
        {
            return ("published", new List<string>());
        }
        WorkflowReview.Snapshot snapshot = new()
        {
            Canvas = canvas,
            Prompt = prompt.ToString(Formatting.None),
            BaseParams = metadata.ToString(Formatting.None),
            BaseValues = values.ToString(Formatting.None),
            Config = record?.Snapshot?.Config,
            Description = description,
            Fingerprint = fingerprint,
            Server = Source,
            Reviewer = Source,
            ReviewedAt = WorkflowReview.Now
        };
        string error = WorkflowReview.Update(id, stored =>
        {
            stored.Snapshot = snapshot;
            stored.Status = WorkflowReview.Published;
            stored.RejectedFingerprint = null;
            stored.RejectReason = null;
            stored.Reviewer = Source;
            stored.ReviewedAt = snapshot.ReviewedAt;
            return null;
        });
        if (error is not null)
        {
            return ("failed", new List<string>() { error });
        }
        Logs.Info($"EcomCraft published the standard workflow {id}.");
        return ("published", new List<string>());
    }

    /// <summary>The status list for administrators: kind, published ID, state and up to five missing nodes or models (names only), plus the current
    /// recipe and the effective model file names (the recipe variant's, or the legacy override when it matched nothing, T118).</summary>
    private static JObject StatusJson(IEnumerable<(string Kind, string Id, string State, List<string> Problems)> items)
    {
        ModelRecipeRules.EffectiveModels effective = ModelRecipes.Current();
        return new JObject()
        {
            ["workflows"] = new JArray(items.Select(item => new JObject()
            {
                ["kind"] = item.Kind,
                ["id"] = item.Id,
                ["state"] = item.State,
                ["problems"] = new JArray(item.Problems ?? new List<string>())
            })),
            ["models"] = new JObject()
            {
                ["unet"] = effective.Files.Unet,
                ["text_encoder"] = effective.Files.TextEncoder,
                ["vae"] = effective.Files.Vae
            },
            ["recipe"] = new JObject()
            {
                ["id"] = effective.Recipe?.Id ?? "",
                ["name"] = effective.Recipe?.Name.ZhCn ?? "",
                ["variant"] = effective.Variant?.Id ?? "",
                ["legacy_unmatched"] = effective.LegacyUnmatched,
                ["problems"] = new JArray(effective.Problems)
            }
        };
    }

    [API.APIDescription("Read the state of the standard workflows generated for the built-in templates (F57), or with action \"init\" generate and publish them now, "
        + "also republishing ones an administrator took down. state is published, taken_down, missing_blueprint, unsupported, missing_dependencies, no_server or failed; "
        + "problems lists missing nodes or models by name, or why the current recipe cannot build a kind. models are the effective model file names (the current "
        + "recipe's variant, or the administrator's legacy override), and recipe names the current recipe and variant. Requires the server-settings permission.",
        "workflows: [{ kind: \"scene\", id: \"系统生成/ecomcraft/scene\", state: \"published\", problems: [] }], models: { unet: \"\", text_encoder: \"\", vae: \"\" }, "
        + "recipe: { id: \"当前配方 id\", name: \"当前配方名\", variant: \"变体 id\", legacy_unmatched: false, problems: [] }")]
    public static Task<JObject> EcomCraftStandardWorkflows(Session session, string action = "")
    {
        if (!StudioApi.CanView(session) || !session.User.HasPermission(Permissions.EditServerSettings))
        {
            return Task.FromResult(StudioApi.Error("此账号没有管理标准工作流的权限。", "bad_permissions"));
        }
        if (action == "init")
        {
            return Task.FromResult(StatusJson(Ensure(true)));
        }
        if (!string.IsNullOrEmpty(action))
        {
            return Task.FromResult(StudioApi.Error("未知的操作。", "invalid_parameters"));
        }
        List<(string, string, string, List<string>)> items;
        lock (Lock)
        {
            items = [.. Kinds.Select(item => Status.TryGetValue(item.Kind, out (string State, List<string> Problems) known)
                ? (item.Kind, item.Id, WorkflowReview.IsPublished(item.Id) ? "published" : known.State, known.Problems)
                : (item.Kind, item.Id, WorkflowReview.IsPublished(item.Id) ? "published" : "not_checked", new List<string>()))];
        }
        return Task.FromResult(StatusJson(items));
    }

    [API.APIDescription("Whether the direct-fusion trial can run now (F84): available once every of its three standard workflows (one per angle count) is "
        + "published. reason is null when available, else the plain-language explanation also shown on the page. Only the trial's availability is "
        + "disclosed here, never nodes, addresses or graphs.", "available: true, reason: null")]
    public static Task<JObject> EcomCraftStudioReferenceEditStatus(Session session)
    {
        if (!StudioApi.CanView(session) || !session.User.HasPermission(EcomCraft.PermUsePublishedWorkflows))
        {
            return Task.FromResult(StudioApi.Error("此账号没有使用模板的权限。", "bad_permissions"));
        }
        string reason = null;
        for (int angles = 1; angles <= 3 && reason is null; angles++)
        {
            if (!WorkflowReview.IsPublished(ReferenceEditId(angles)))
            {
                reason = Unavailable(ReferenceEditKind(angles));
            }
        }
        return Task.FromResult(new JObject() { ["available"] = reason is null, ["reason"] = reason });
    }
}
